"""Builds the repository and its history in the current folder."""
import os, subprocess
from pathlib import Path

HISTORY = [('Start slugger', None, {'slugger/__init__.py': '', 'slugger/core.py': '\n"""Slugs for URLs."""\nimport re\n\n\ndef slugify(title):\n    return re.sub(r"[^a-z0-9]", "-", title.lower()).strip("-")\n', 'README.md': '# slugger\n\nSlugs for our URLs.\n'}), ('Add tests', None, {'tests/__init__.py': '', 'tests/test_core.py': '\nimport unittest\n\nfrom slugger.core import slugify\n\n\nclass Slugs(unittest.TestCase):\n    def test_words(self):\n        self.assertEqual(slugify("Hello,  World!"), "hello-world")\n\n    def test_edges(self):\n        self.assertEqual(slugify("  --Spaces--  "), "spaces")\n\n\nif __name__ == "__main__":\n    unittest.main()\n'}), ('Collapse repeated separators', 'v1.1', {'slugger/core.py': '\n"""Slugs for URLs."""\nimport re\n\n\ndef slugify(title):\n    return re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-")\n'}), ('Add max_length', 'v1.2', {'slugger/core.py': '\n"""Slugs for URLs."""\nimport re\n\n\ndef slugify(title, max_length=None):\n    slug = re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-")\n    if max_length and len(slug) > max_length:\n        slug = slug[:max_length + 1].rsplit("-", 1)[0][:max_length]\n    return slug\n', 'tests/test_core.py': '\nimport unittest\n\nfrom slugger.core import slugify\n\n\nclass Slugs(unittest.TestCase):\n    def test_words(self):\n        self.assertEqual(slugify("Hello,  World!"), "hello-world")\n\n    def test_edges(self):\n        self.assertEqual(slugify("  --Spaces--  "), "spaces")\n\n    def test_max_length(self):\n        self.assertEqual(slugify("the quick brown fox", max_length=10), "the-quick")\n\n\nif __name__ == "__main__":\n    unittest.main()\n'}), ('Describe max_length in the README', None, {'README.md': '# slugger\n\nSlugs for our URLs.\n\n`slugify(title, max_length=40)` cuts at a word.\n'}), ('Tidy the separator handling', None, {'slugger/core.py': '\n"""Slugs for URLs."""\nimport re\n\nSEPARATORS = re.compile(r"[^a-z]+")\n\n\ndef slugify(title, max_length=None):\n    slug = SEPARATORS.sub("-", title.lower()).strip("-")\n    if max_length and len(slug) > max_length:\n        slug = slug[:max_length + 1].rsplit("-", 1)[0][:max_length]\n    return slug\n'}), ('Add a changelog', None, {'CHANGELOG.md': '# Changes\n\n- 1.2: max_length\n- 1.1: repeated separators collapse\n'}), ('Fold common accents', 'v1.3', {'slugger/core.py': '\n"""Slugs for URLs."""\nimport re\n\nSEPARATORS = re.compile(r"[^a-z]+")\nFOLD = str.maketrans("àáâäçèéêëìíîïñòóôöùúûüß", "aaaaceeeeiiiinoooouuuus")\n\n\ndef slugify(title, max_length=None):\n    slug = SEPARATORS.sub("-", title.lower().translate(FOLD)).strip("-")\n    if max_length and len(slug) > max_length:\n        slug = slug[:max_length + 1].rsplit("-", 1)[0][:max_length]\n    return slug\n', 'tests/test_core.py': '\nimport unittest\n\nfrom slugger.core import slugify\n\n\nclass Slugs(unittest.TestCase):\n    def test_words(self):\n        self.assertEqual(slugify("Hello,  World!"), "hello-world")\n\n    def test_edges(self):\n        self.assertEqual(slugify("  --Spaces--  "), "spaces")\n\n    def test_max_length(self):\n        self.assertEqual(slugify("the quick brown fox", max_length=10), "the-quick")\n\n    def test_accents(self):\n        self.assertEqual(slugify("Crème Brûlée"), "creme-brulee")\n\n\nif __name__ == "__main__":\n    unittest.main()\n'}), ('Add drop_stopwords', None, {'slugger/core.py': '\n"""Slugs for URLs."""\nimport re\n\nSEPARATORS = re.compile(r"[^a-z]+")\nFOLD = str.maketrans("àáâäçèéêëìíîïñòóôöùúûüß", "aaaaceeeeiiiinoooouuuus")\nSTOPWORDS = {"a", "an", "the", "of", "and"}\n\n\ndef slugify(title, max_length=None, drop_stopwords=False):\n    slug = SEPARATORS.sub("-", title.lower().translate(FOLD)).strip("-")\n    if drop_stopwords:\n        slug = "-".join(word for word in slug.split("-") if word not in STOPWORDS)\n    if max_length and len(slug) > max_length:\n        slug = slug[:max_length + 1].rsplit("-", 1)[0][:max_length]\n    return slug\n', 'tests/test_core.py': '\nimport unittest\n\nfrom slugger.core import slugify\n\n\nclass Slugs(unittest.TestCase):\n    def test_words(self):\n        self.assertEqual(slugify("Hello,  World!"), "hello-world")\n\n    def test_edges(self):\n        self.assertEqual(slugify("  --Spaces--  "), "spaces")\n\n    def test_max_length(self):\n        self.assertEqual(slugify("the quick brown fox", max_length=10), "the-quick")\n\n    def test_accents(self):\n        self.assertEqual(slugify("Crème Brûlée"), "creme-brulee")\n\n    def test_stopwords(self):\n        self.assertEqual(slugify("The Art of War", drop_stopwords=True), "art-war")\n\n\nif __name__ == "__main__":\n    unittest.main()\n'}), ('Changelog for 1.3 and the stopwords', None, {'CHANGELOG.md': '# Changes\n\n- next: drop_stopwords\n- 1.3: accents fold\n- 1.2: max_length\n- 1.1: repeated separators collapse\n'})]

def git(*args, when=None):
    env = dict(os.environ, GIT_AUTHOR_NAME="Dana", GIT_AUTHOR_EMAIL="dana@example.org", GIT_COMMITTER_NAME="Dana", GIT_COMMITTER_EMAIL="dana@example.org")
    if when:
        env.update(GIT_AUTHOR_DATE=when, GIT_COMMITTER_DATE=when)
    return subprocess.run(["git", "-c", "core.autocrlf=false", "-c", "commit.gpgsign=false", *args], check=True, capture_output=True, text=True, env=env).stdout


git("init", "-q", "-b", "main")
for n, (subject, tag, files) in enumerate(HISTORY):
    for rel, text in files.items():
        Path(rel).parent.mkdir(parents=True, exist_ok=True)
        Path(rel).write_bytes(text.lstrip("\n").encode("utf-8"))
    git("add", "-A")
    git("commit", "-q", "-m", subject, when=f"2026-09-{n + 1:02d}T10:00:00+00:00")
    if tag:
        git("tag", tag)
